    boxed->data = start;
    boxed->size = line_len;
    if (i == remaining) {
        s->cursor = s->src_len;
        s->done = true;
    } else {
        s->cursor += i + 1;
        if (s->cursor >= s->src_len) s->done = true;
    }
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
